#define DBG(x) cerr<<(#x)<<"="<<x<<"\n";

#define FOREACH(it,x) for(__typeof(x.begin()) it=x.begin();it!=x.end();++it)
typedef unsigned long long ull;
typedef long long ll;
const int MAXN = 500005;

template <class T,class U>inline void Max(T &a,U b){if(a<b)a=b;}
template <class T,class U>inline void Min(T &a,U b){if(a>b)a=b;}

inline void add_mod(int &a,int b){a+=b;while(a>=MOD)a-=MOD;}
inline int gcd(int a, int b){if(b == 0)return a; return gcd(b, a%b);}
int pow_mod(int a,int b){
    int ans=1;
    while(b){
        if(b&1)ans=ans*(ll)a%MOD;
        a=(ll)a*a%MOD;b>>=1;
    }
    return ans;
}

const int M = 105;
int start[51], idx[51][M];
pii roads[51];
int edge_cnt, head[MAXN], dist[MAXN], prev_edge[MAXN], inq[MAXN];
struct Edge{
    int to, cap, cost, next;
}edges[MAXN<<2];
void add_edge(int a, int b, int cap, int cost){
    edges[edge_cnt] = {b, cap, cost, head[a]}; head[a] = edge_cnt++;
    edges[edge_cnt] = {a, 0, -cost, head[b]}; head[b] = edge_cnt++;
}
bool spfa(int s, int t){
    rep(i,0,t+1) dist[i] = INF, inq[i] = 0;
    queue<int> q;
    q.push(s); dist[s] = 0;
    while(!q.empty()){
        int u = q.front(); q.pop(); inq[u] = 0;
        for(int i = head[u]; ~i; i = edges[i].next){
            int v = edges[i].to;
            if(edges[i].cap && dist[v] > dist[u] + edges[i].cost){
                dist[v] = dist[u] + edges[i].cost;
                prev_edge[v] = i;
                if(!inq[v]){
                    inq[v] = 1;
                    q.push(v);
                }
            }
        }
    }
    return dist[t] < INF;
}
int min_cost_flow(int s, int t){
    int cost = 0, flow = 0;
    while(spfa(s, t)){
        int x = t, f = INF;
        while(x != s){
            Min(f, edges[prev_edge[x]].cap);
            x = edges[prev_edge[x] ^ 1].to;
        }
        cost += f * dist[t];
        flow += f;
        x = t;
        while(x != s){
            edges[prev_edge[x]].cap -= f;
            edges[prev_edge[x] ^ 1].cap += f;
            x = edges[prev_edge[x] ^ 1].to;
        }
    }
    DBG(flow)
    return cost;
}
