    rep(i,0,M) add_edge(idx[0][i], t, K, C * i);
    rep(i,0,n){
        rep(j,0,M-1){
            add_edge(idx[i][j], idx[i][j+1], K, 0);
        }
    }
    rep(i,0,m){
        int x = roads[i].X, y = roads[i].Y;
        rep(j,0,M-1){
            rep(k,0,K){
                add_edge(idx[x][j], idx[y][j+1], 1, D*(2*k + 1));
                add_edge(idx[y][j], idx[x][j+1], 1, D*(2*k + 1));
            }
        }
    }
    int ans = min_cost_flow(s, t);
    cout << ans << endl;
}
